static int pal(char*s,int l,int r){while(l<r)if(s[l++]!=s[r--])return 0;return 1;}static void f(char*s,int n,int st,char**v,int len,char****o,int**cols,int*c,int*cap){if(st==n){if(*c==*cap){*cap*=2;*o=realloc(*o,*cap*sizeof(char**));*cols=realloc(*cols,*cap*sizeof(int));}char**r=malloc(len*sizeof(char*));for(int i=0;i<len;i++)r[i]=strdup(v[i]);(*o)[*c]=r;(*cols)[(*c)++]=len;return;}for(int e=st;e<n;e++)if(pal(s,st,e)){int z=e-st+1;char*x=malloc(z+1);memcpy(x,s+st,z);x[z]=0;v[len]=x;f(s,n,e+1,v,len+1,o,cols,c,cap);free(x);}}char*** partition(char*s,int*rs,int**rc){int n=strlen(s),cap=16,c=0;char***o=malloc(cap*sizeof(char**));int*cols=malloc(cap*sizeof(int));char**v=malloc(n*sizeof(char*));f(s,n,0,v,0,&o,&cols,&c,&cap);free(v);*rs=c;*rc=cols;return o;}
